// CPU-only native container-click hashes and typed HashOps reference operations.
import com.google.gson.*;import java.nio.file.*;import java.util.*;import java.util.stream.*;import java.nio.ByteBuffer;
import com.google.common.hash.HashCode;import com.mojang.datafixers.util.Pair;
import net.minecraft.SharedConstants;import net.minecraft.server.Bootstrap;import net.minecraft.util.HashOps;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.core.component.*;import net.minecraft.resources.RegistryOps;import net.minecraft.network.*;import net.minecraft.network.protocol.game.*;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import net.minecraft.world.item.component.*;import net.minecraft.nbt.*;import io.netty.buffer.Unpooled;
public class ExportHashOps {
 static final HashOps OPS=HashOps.CRC32C_INSTANCE;
 static JsonObject scalar(String type,Object value){var n=new JsonObject();n.addProperty("type",type);if(value instanceof Boolean b)n.addProperty("value",b);else if(value instanceof Number n1)n.addProperty("value",n1);else if(value!=null)n.addProperty("value",value.toString());return n;}
 static JsonObject string(String text){var n=new JsonObject();n.addProperty("type","string");var u=new JsonArray();for(char c:text.toCharArray())u.add((int)c);n.add("units",u);return n;}
 static JsonObject seq(String type,JsonArray values){var n=new JsonObject();n.addProperty("type",type);n.add("values",values);return n;}
 static HashCode hash(JsonObject n){return switch(n.get("type").getAsString()){
  case "empty"->OPS.empty();case "bool"->OPS.createBoolean(n.get("value").getAsBoolean());case "byte"->OPS.createByte(n.get("value").getAsByte());case "short"->OPS.createShort(n.get("value").getAsShort());case "int"->OPS.createInt(n.get("value").getAsInt());case "long"->OPS.createLong(Long.parseLong(n.get("value").getAsString()));case "float"->OPS.createFloat(Float.intBitsToFloat(n.get("value").getAsInt()));case "double"->OPS.createDouble(Double.longBitsToDouble(Long.parseLong(n.get("value").getAsString())));
  case "string"->{var u=n.getAsJsonArray("units");var chars=new char[u.size()];for(int i=0;i<chars.length;i++)chars[i]=(char)u.get(i).getAsInt();yield OPS.createString(new String(chars));}
  case "list"->OPS.createList(n.getAsJsonArray("values").asList().stream().map(v->hash(v.getAsJsonObject())));
  case "map"->OPS.createMap(n.getAsJsonArray("values").asList().stream().map(v->Pair.of(hash(v.getAsJsonArray().get(0).getAsJsonObject()),hash(v.getAsJsonArray().get(1).getAsJsonObject()))));
  case "bytes"->{var a=n.getAsJsonArray("values");var bytes=new byte[a.size()];for(int i=0;i<a.size();i++)bytes[i]=a.get(i).getAsByte();yield OPS.createByteList(ByteBuffer.wrap(bytes));}
  case "ints"->OPS.createIntList(n.getAsJsonArray("values").asList().stream().mapToInt(JsonElement::getAsInt));case "longs"->OPS.createLongList(n.getAsJsonArray("values").asList().stream().mapToLong(v->Long.parseLong(v.getAsString())));default->throw new IllegalArgumentException(n.toString());};}
 static JsonObject random(Random r,int depth){int type=r.nextInt(depth>0?13:10);return switch(type){case 0->scalar("empty",null);case 1->scalar("bool",r.nextBoolean());case 2->scalar("byte",(byte)r.nextInt());case 3->scalar("short",(short)r.nextInt());case 4->scalar("int",r.nextInt());case 5->scalar("long",r.nextLong()+"");case 6->scalar("float",r.nextInt());case 7->scalar("double",r.nextLong()+"");case 8->string(new String(new char[]{(char)r.nextInt(65536),(char)r.nextInt(65536),'\0','Ё',(char)0xd83d,(char)0xde00}));case 9->{var a=new JsonArray();for(int i=0;i<r.nextInt(8);i++)a.add((byte)r.nextInt());yield seq("bytes",a);}case 10->{var a=new JsonArray();for(int i=0;i<r.nextInt(5);i++)a.add(random(r,depth-1));yield seq("list",a);}case 11->{var a=new JsonArray();for(int i=0;i<r.nextInt(5);i++){var pair=new JsonArray();pair.add(random(r,depth-1));pair.add(random(r,depth-1));a.add(pair);}yield seq("map",a);}default->{var a=new JsonArray();for(int i=0;i<r.nextInt(8);i++)a.add(r.nextInt());yield seq("ints",a);}};}
 static String stack(ItemStack stack){var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{ClientboundSetCursorItemPacket.STREAM_CODEC.encode(b,new ClientboundSetCursorItemPacket(stack));var bytes=new byte[b.readableBytes()];b.readBytes(bytes);return Base64.getEncoder().encodeToString(bytes);}finally{b.release();}}
 public static void main(String[] args)throws Exception{
  SharedConstants.tryDetectVersion();Bootstrap.bootStrap();var dl=net.minecraft.data.registries.VanillaRegistries.createLookup();var sl=RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);var keys=sl.listRegistryKeys().collect(Collectors.toSet());var lookup=HolderLookup.Provider.create(Stream.concat(sl.listRegistries(),dl.listRegistries().filter(r->!keys.contains(r.key()))));BuiltInRegistries.DATA_COMPONENT_INITIALIZERS.build(lookup).forEach(DataComponentInitializers.PendingComponents::apply);var ops=RegistryOps.create(OPS,lookup);
  var primitives=new JsonArray();var random=new Random(776);for(int i=0;i<2000;i++){var node=random(random,5);var row=new JsonObject();row.add("node",node);row.addProperty("hash",Integer.toUnsignedLong(hash(node).asInt()));primitives.add(row);}for(String type:List.of("list","map","bytes","ints","longs")){var node=seq(type,new JsonArray());var row=new JsonObject();row.add("node",node);row.addProperty("hash",Integer.toUnsignedLong(hash(node).asInt()));primitives.add(row);}
  var stacks=new JsonArray();
  for(int type=0;type<12;type++){var item=new ItemStack(Items.DIAMOND,23);switch(type){case 0->{}case 1->item.set(DataComponents.DAMAGE,7);case 2->item.set(DataComponents.CUSTOM_NAME,Component.literal("Имя 😀"));case 3->item.set(DataComponents.CUSTOM_NAME,Component.literal("Имя").withStyle(net.minecraft.ChatFormatting.GOLD).append(Component.literal(" хвост").withStyle(net.minecraft.ChatFormatting.BOLD)));case 4->item.set(DataComponents.LORE,new ItemLore(List.of(Component.literal("Линия 1"),Component.literal("Line 2").withStyle(net.minecraft.ChatFormatting.ITALIC))));case 5->item.set(DataComponents.MAX_STACK_SIZE,32);case 6->item.set(DataComponents.UNBREAKABLE,net.minecraft.util.Unit.INSTANCE);case 7->item.set(DataComponents.ITEM_MODEL,net.minecraft.resources.Identifier.withDefaultNamespace("diamond"));case 8->item.set(DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);case 9->{var tag=new CompoundTag();tag.putString("server","test");tag.putByte("bool",(byte)1);tag.putInt("integer",42);tag.putByteArray("bytes",new byte[]{-1,0,1});tag.putIntArray("ints",new int[]{3,2,1});item.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));}case 10->item.remove(DataComponents.MAX_STACK_SIZE);case 11->{item.set(DataComponents.RARITY,Rarity.EPIC);item.set(DataComponents.REPAIR_COST,3);item.set(DataComponents.DYED_COLOR,new DyedItemColor(0xffaabb));}}
   var row=new JsonObject();row.addProperty("type",type);row.addProperty("body",stack(item));var hashes=new JsonObject();for(var c:item.getComponentsPatch().entrySet())if(c.getValue().isPresent()){var component=TypedDataComponent.createUnchecked((DataComponentType)c.getKey(),c.getValue().get());hashes.addProperty(BuiltInRegistries.DATA_COMPONENT_TYPE.getId(c.getKey())+"",Integer.toUnsignedLong(((HashCode)component.encodeValue(ops).getOrThrow()).asInt()));}row.add("hashes",hashes);
   net.minecraft.network.HashedPatchMap.HashGenerator generator=c->c.encodeValue(ops).getOrThrow().asInt();var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),sl);try{HashedStack.STREAM_CODEC.encode(b,HashedStack.create(item,generator));var data=new byte[b.readableBytes()];b.readBytes(data);row.addProperty("hashed",Base64.getEncoder().encodeToString(data));}finally{b.release();}stacks.add(row);
  }
  var root=new JsonObject();root.add("primitives",primitives);root.add("stacks",stacks);Files.writeString(Path.of(args[0]),new Gson().toJson(root));
 }
}
